import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";import{j as i}from"./chunks/assets.DMkeNHu3.js";var a=JSON.parse(`{"title":"Category Management Guide","description":"","frontmatter":{},"headers":[],"relativePath":"02-consumer/04-category.md","filePath":"02-consumer/04-category.md"}`),o={name:`02-consumer/04-category.md`};function s(n,a,o,s,c,l){return r(),t(`div`,null,[...a[0]||=[e(`<h1 id="category-management-guide" tabindex="-1">Category Management Guide <a class="header-anchor" href="#category-management-guide" aria-label="Permalink to “Category Management Guide”">​</a></h1><h2 id="page-overview" tabindex="-1">Page Overview <a class="header-anchor" href="#page-overview" aria-label="Permalink to “Page Overview”">​</a></h2><p>The category editing page is used to manage information, textual content, images, the category&#39;s position in the site structure, and its display and SEO settings.</p><p>On this page, you can define the category, link it to a parent category, specify the images required by the template, and, if needed, configure the Schema Markup for the category page or its child products.</p><p>Figure 1 - Overview of the category editing page. The numbers indicate the locations of the form sections.</p><p><img src="`+i+`" alt="category.webp" width="1916" height="1569"></p><h2 id="_1-editing-the-category-s-main-information" tabindex="-1">1. Editing the Category&#39;s Main Information <a class="header-anchor" href="#_1-editing-the-category-s-main-information" aria-label="Permalink to “1. Editing the Category&#39;s Main Information”">​</a></h2><p>This section manages the category&#39;s main information and content.</p><table tabindex="0"><thead><tr><th>Field</th><th>Purpose</th></tr></thead><tbody><tr><td>Category name</td><td>Specifies the category name.</td></tr><tr><td>Category slug</td><td>The text identifier used in the category page URL. According to the panel guide, if this field is empty, its value is generated automatically.</td></tr><tr><td>Subtitle</td><td>Specifies the category subtitle.</td></tr><tr><td>Group Parent</td><td>Selects the parent category to place the current category in the hierarchy.</td></tr><tr><td>Hide in menu</td><td>Specifies whether the category should be hidden from menus that display child categories. This option alone does not mean that the category page is disabled.</td></tr><tr><td>Description</td><td>Adds the category description. This section uses a text editor for writing and formatting content.</td></tr></tbody></table><p>The category name, subtitle, and description support multilingual content.</p><p>Note: Hiding a category from the menu is different from disabling it. This option controls its display in menus that show child categories.</p><blockquote><p>Important note: Click the gray button next to the title, which has a paint palette icon, to design a separate template for this category.</p></blockquote><h2 id="_2-selecting-a-category-icon" tabindex="-1">2. Selecting a Category Icon <a class="header-anchor" href="#_2-selecting-a-category-icon" aria-label="Permalink to “2. Selecting a Category Icon”">​</a></h2><p>In this section, you can select the category icon. The selected icon can be used to visually represent the category in parts of the site that support icons.</p><h2 id="_3-feature-image" tabindex="-1">3. Feature Image <a class="header-anchor" href="#_3-feature-image" aria-label="Permalink to “3. Feature Image”">​</a></h2><p>This section is for selecting the category&#39;s main image. The selected image may be displayed in lists or other parts of the site that use a feature image to represent a category.</p><p>To select an image, use the file upload option in this section.</p><h2 id="_4-background-image" tabindex="-1">4. Background Image <a class="header-anchor" href="#_4-background-image" aria-label="Permalink to “4. Background Image”">​</a></h2><p>In this section, you can specify the category&#39;s background image. This image is available for some template layouts and may be used in the design of various parts of the site.</p><p>Whether this image is used depends on the template&#39;s design and settings.</p><h2 id="_5-svg-image" tabindex="-1">5. SVG Image <a class="header-anchor" href="#_5-svg-image" aria-label="Permalink to “5. SVG Image”">​</a></h2><p>This section is for selecting an image in SVG format. In some templates, an SVG image can be used alongside the feature image or in sections specifically designed for it.</p><p>Note: The feature image, background image, and SVG image do not serve the same purpose. Choose each one based on the template&#39;s requirements and the intended display location.</p><h2 id="_6-category-attachments" tabindex="-1">6. Category Attachments <a class="header-anchor" href="#_6-category-attachments" aria-label="Permalink to “6. Category Attachments”">​</a></h2><p>This section manages attachments associated with the category.</p><p>The Add attachment button lets you start the process of adding an attachment. The number next to the button indicates how many attachments are displayed in this section.</p><p>Details about the types of attachments that can be added and how they are displayed depend on how attachments work in the panel.</p><h2 id="_7-canonical-url" tabindex="-1">7. Canonical URL <a class="header-anchor" href="#_7-canonical-url" aria-label="Permalink to “7. Canonical URL”">​</a></h2><p>The Canonical field is used to enter the category page&#39;s canonical URL in the SEO settings.</p><p>This URL helps search engines identify the canonical version of the page, which is important when managing similar pages or URLs with identical content.</p><p>Note: Enter this value carefully. The Canonical URL should match the page you want to identify as the canonical version.</p><h2 id="_8-default-schema-markup-for-child-products" tabindex="-1">8. Default Schema Markup for Child Products <a class="header-anchor" href="#_8-default-schema-markup-for-child-products" aria-label="Permalink to “8. Default Schema Markup for Child Products”">​</a></h2><p>This section defines the Schema Markup for the category&#39;s child products - that is, the structured data intended for products associated with this category.</p><p>Schema Markup is a type of structured data that presents content information in a format search engines can understand. For example, a <code>Product</code> schema may specify a product&#39;s name, description, and price.</p><h3 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to “How to Use”">​</a></h3><p>Enter the Schema Markup in the editor. You can add one or more schemas in this section; there is no limit to one schema.</p><p>For example, a schema could look like this:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;script type=&quot;application/ld+json&quot;&gt;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;@context&quot;: &quot;https://schema.org&quot;,</span></span>
<span class="line"><span>  &quot;@type&quot;: &quot;Product&quot;,</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;%name%&quot;,</span></span>
<span class="line"><span>  &quot;description&quot;: &quot;%desc%&quot;,</span></span>
<span class="line"><span>  &quot;offers&quot;: {</span></span>
<span class="line"><span>    &quot;@type&quot;: &quot;Offer&quot;,</span></span>
<span class="line"><span>    &quot;price&quot;: &quot;%price%&quot;,</span></span>
<span class="line"><span>    &quot;priceCurrency&quot;: &quot;USD&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>&lt;/script&gt;</span></span></code></pre></div><p>In this example, <code>%name%</code>, <code>%desc%</code>, and <code>%price%</code> are variables used to replace the corresponding product values. The system replaces the variables when the content is displayed.</p><p>The example above is only an example of a usable structure; the fields and values in each schema must be valid and appropriate for the content type and its actual information.</p><h3 id="variable-insertion-buttons" tabindex="-1">Variable Insertion Buttons <a class="header-anchor" href="#variable-insertion-buttons" aria-label="Permalink to “Variable Insertion Buttons”">​</a></h3><p>Above the editor are buttons for inserting replaceable values, such as <code>Name</code>, <code>Description</code>, <code>Price</code>, and other items shown in the panel.</p><ol><li>To view the guide for a variable, hover over its button. The guide displays the related value or description.</li><li>If you have selected part of the text in the editor, clicking a variable button replaces the selected text with the corresponding variable.</li><li>If no text is selected, the variable is inserted at the current cursor position.</li></ol><p>For example, clicking the <code>Name</code> button can insert <code>%name%</code> where needed. This lets you use the appropriate variable instead of entering a fixed value directly.</p><h3 id="selecting-syntax" tabindex="-1">Selecting Syntax <a class="header-anchor" href="#selecting-syntax" aria-label="Permalink to “Selecting Syntax”">​</a></h3><p>The <code>Syntax</code> option is to the right of the variable buttons. Use it to select the code syntax in the editor. In the image, the selected value is <code>HTML</code>.</p><p>Since Schema Markup can be written in different formats, choose the format that suits the content you are entering.</p><h2 id="_9-category-page-schema-markup" tabindex="-1">9. Category Page Schema Markup <a class="header-anchor" href="#_9-category-page-schema-markup" aria-label="Permalink to “9. Category Page Schema Markup”">​</a></h2><p>This section defines the Schema Markup for the category page itself, not its child products.</p><p>To define structured data for the category page, enter the relevant code in this editor. As in the previous section, you can enter multiple schemas; this section is not limited to one schema.</p><p>The buttons above the editor are also used to insert replaceable variables into the schema text. They work similarly to those in section 8:</p><ul><li>Hover over a button to display the variable guide.</li><li>Select text and click a button to replace the selected text.</li><li>If no text is selected, the variable is inserted at the cursor position.</li><li>The system replaces the variables when the content is displayed.</li></ul><p>In this section, the variables shown in the image include items such as <code>App name</code>, <code>Name</code>, <code>Subtitle</code>, <code>Description</code>, <code>URL</code>, and <code>Image</code>.</p><p>Difference Between the Two Schema Markup Sections</p><table tabindex="0"><thead><tr><th>Section</th><th>Purpose</th></tr></thead><tbody><tr><td>Default Schema Markup for Child Products (number 8)</td><td>Defines structured data for products associated with the category</td></tr><tr><td>Category Page Schema Markup (number 9)</td><td>Defines structured data for the category page itself</td></tr></tbody></table><p>Therefore, before entering code, first determine whether you want to define information for the child products or for the category page.</p><h2 id="saving-changes" tabindex="-1">Saving Changes <a class="header-anchor" href="#saving-changes" aria-label="Permalink to “Saving Changes”">​</a></h2><p>After completing the information and configuring the required sections, use the Save button at the bottom of the page to save your changes.</p><p>Before saving, it is a good idea to review the category name and URL, parent category, images, and content entered in the Schema Markup sections to ensure that the information matches your intended purpose.</p>`,59)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};